orithm/src/map.ts", "../../../node_modules/@lumino/algorithm/src/range.ts", "../../../node_modules/@lumino/algorithm/src/reduce.ts", "../../../node_modules/@lumino/algorithm/src/repeat.ts", "../../../node_modules/@lumino/algorithm/src/retro.ts", "../../../node_modules/@lumino/algorithm/src/sort.ts", "../../../node_modules/@lumino/algorithm/src/stride.ts", "../../../node_modules/@lumino/algorithm/src/string.ts", "../../../node_modules/@lumino/algorithm/src/take.ts", "../../../node_modules/@lumino/algorithm/src/zip.ts", "../../../node_modules/@lumino/domutils/src/clipboard.ts", "../../../node_modules/@lumino/domutils/src/element.ts", "../../../node_modules/@lumino/domutils/src/platform.ts", "../../../node_modules/@lumino/domutils/src/selector.ts", "../../../node_modules/@lumino/collections/src/bplustree.ts", "../../../node_modules/@lumino/collections/src/linkedlist.ts", "../../../node_modules/@lumino/messaging/node_modules/tslib/tslib.es6.js", "../../../node_modules/@lumino/messaging/src/index.ts", "../../../node_modules/@lumino/properties/src/index.ts", "../../../node_modules/@lumino/signaling/src/index.ts", "../../../node_modules/@lumino/disposable/node_modules/tslib/tslib.es6.js", "../../../node_modules/@lumino/disposable/src/index.ts", "../../../node_modules/@lumino/dragdrop/src/index.ts", "../../../node_modules/@lumino/keyboard/src/index.ts", "../../../node_modules/@lumino/commands/node_modules/tslib/tslib.es6.js", "../../../node_modules/@lumino/commands/src/index.ts", "../../../node_modules/@lumino/virtualdom/node_modules/tslib/tslib.es6.js", "../../../node_modules/@lumino/virtualdom/src/index.ts", "../../../node_modules/@lumino/widgets/node_modules/tslib/tslib.es6.js", "../../../node_modules/@lumino/widgets/src/boxengine.ts", "../../../node_modules/@lumino/widgets/src/title.ts", "../../../node_modules/@lumino/widgets/src/widget.ts", "../../../node_modules/@lumino/widgets/src/layout.ts", "../../../node_modules/@lumino/widgets/src/panellayout.ts", "../../../node_modules/@lumino/widgets/src/utils.ts", "../../../node_modules/@lumino/widgets/src/splitlayout.ts", "../../../node_modules/@lumino/widgets/src/accordionlayout.ts", "../../../node_modules/@lumino/widgets/src/panel.ts", "../../../node_modules/@lumino/widgets/src/splitpanel.ts", "../../../node_modules/@lumino/widgets/src/accordionpanel.ts", "../../../node_modules/@lumino/widgets/src/boxlayout.ts", "../../../node_modules/@lumino/widgets/src/boxpanel.ts", "../../../node_modules/@lumino/widgets/src/commandpalette.ts", "../../../node_modules/@lumino/widgets/src/menu.ts", "../../../node_modules/@lumino/widgets/src/contextmenu.ts", "../../../node_modules/@lumino/widgets/src/tabbar.ts", "../../../node_modules/@lumino/widgets/src/docklayout.ts", "../../../node_modules/@lumino/widgets/src/dockpanel.ts", "../../../node_modules/@lumino/widgets/src/focustracker.ts", "../../../node_modules/@lumino/widgets/src/gridlayout.ts", "../../../node_modules/@lumino/widgets/src/menubar.ts", "../../../node_modules/@lumino/widgets/src/scrollbar.ts", "../../../node_modules/@lumino/widgets/src/singletonlayout.ts", "../../../node_modules/@lumino/widgets/src/stackedlayout.ts", "../../../node_modules/@lumino/widgets/src/stackedpanel.ts", "../../../node_modules/@lumino/widgets/src/tabpanel.ts", "../../../node_modules/@jupyter-widgets/base/lib/widget_layout.js", "../../../node_modules/@jupyter-widgets/base/lib/widget_style.js", "../../../node_modules/@jupyter-widgets/base/lib/services-shim.js", "../../../node_modules/@jupyter-widgets/base/lib/viewlist.js", "../../../node_modules/@jupyter-widgets/base/lib/registry.js", "../src/lib/utils/deserialize-matrix.js", "../src/lib/jupyter-transport-model.js", "../src/lib/jupyter-transport-view.js", "../../core/src/scripting/lumagl.ts", "../../core/src/scripting/loadersgl.ts"],
  "sourcesContent": ["// Do not name these variables the same as the global objects - will break bundling\nconst global_ = globalThis;\nconst window_ = globalThis as unknown as Window;\nconst document_ = globalThis.document || ({} as Document);\nconst process_ = globalThis.process || {};\nconst console_ = globalThis.console;\nconst navigator_ = globalThis.navigator || ({} as Navigator);\n\nexport {\n  global_ as global,\n  global_ as self,\n  window_ as window,\n  document_ as document,\n  process_ as process,\n  console_ as console,\n  navigator_ as navigator\n};\n", "// based on https://github.com/cheton/is-electron\n// https://github.com/electron/electron/issues/2288\n/* eslint-disable complexity */\nexport function isElectron(mockUserAgent?: string): boolean {\n  // Renderer process\n  // @ts-expect-error\n  if (typeof window !== 'undefined' && window.process?.type === 'renderer') {\n    return true;\n  }\n  // Main process\n  // eslint-disable-next-line\n  if (typeof process !== 'undefined' && Boolean(process.versions?.['electron'])) {\n    return true;\n  }\n  // Detect the user agent when the `nodeIntegration` option is set to true\n  const realUserAgent = typeof navigator !== 'undefined' && navigator.userAgent;\n  const userAgent = mockUserAgent || realUserAgent;\n  return Boolean(userAgent && userAgent.indexOf('Electron') >= 0);\n}\n", "// This function is needed in initialization stages,\n// make sure it can be imported in isolation\n\nimport {isElectron} from './is-electron';\n\n/** Check if in browser by duck-typing Node context */\nexport function isBrowser(): boolean {\n  const isNode =\n    // @ts-expect-error\n    typeof process === 'object' && String(process) === '[object process]' && !process?.browser;\n  return !isNode || isElectron();\n}\n", "// Copyright (c) 2017 Uber Technologies, Inc.\n//\n// Permission is hereby granted, free of charge, to any person obtaining a copy\n// of this software and associated documentation files (the \"Software\"), to deal\n// in the Software without restriction, including without limitation the rights\n// to use, copy, modify, merge, publish, distribute, sublicense, and/or sell\n// copies of the Software, and to permit persons to whom the Software is\n// furnished to do so, subject to the following conditions:\n//\n// The above copyright notice and this permission notice shall be included in\n// all copies or substantial portions of the Software.\n//\n// THE SOFTWARE IS PROVIDED \"AS IS\", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR\n// IMPLIED, INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY,\n// FITNESS FOR A PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE\n// AUTHORS OR COPYRIGHT HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER\n// LIABILITY, WHETHER IN AN ACTION OF CONTRACT, TORT OR OTHERWISE, ARISING FROM,\n// OUT OF OR IN CONNECTION WITH THE SOFTWARE OR THE USE OR OTHER DEALINGS IN\n// THE SOFTWARE.\n\n// This function is needed in initialization stages,\n// make sure it can be imported in isolation\n\nimport {isBrowser} from './is-browser';\nimport {isElectron} from './is-electron';\nimport {navigator} from './globals';\n\ndeclare global {\n  var chrome: boolean; // eslint-disable-line no-var\n  var safari: boolean; // eslint-disable-line no-var\n  var mozInnerScreenX: number; // eslint-disable-line no-var\n}\n\nexport function isMobile(): boolean {\n  return typeof globalThis.orientation !== 'undefined';\n}\n\n// Simple browser detection\n// `mockUserAgent` parameter allows user agent to be overridden for testing\n/* eslint-disable complexity */\nexport function getBrowser(\n  mockUserAgent?: string\n): 'Node' | 'Electron' | 'Chrome' | 'Firefox' | 'Safari' | 'Edge' | 'Unknown' {\n  if (!mockUserAgent && !isBrowser()) {\n    return 'Node';\n  }\n  if (isElectron(mockUserAgent)) {\n    return 'Electron';\n  }\n\n  const userAgent = mockUserAgent || navigator.userAgent || '';\n\n  // NOTE: Order of tests matter, as many agents list Chrome etc.\n  if (userAgent.indexOf('Edge') > -1) {\n    return 'Edge';\n  }\n  if (globalThis.chrome) {\n    return 'Chrome';\n  }\n  if (globalThis.safari) {\n    return 'Safari';\n  }\n  if (globalThis.mozInnerScreenX) {\n    return 'Firefox';\n  }\n  return 'Unknown';\n}\n", "// Extract injected version from package.json (injected by babel plugin)\n// @ts-expect-error\nexport const VERSION = typeof __VERSION__ !== 'undefined' ? __VERSION__ : 'untranspiled source';\n\n// ENVIRONMENT\nexport {self, window, global, document, process, console} from './lib/globals';\nexport {isBrowser} from './lib/is-browser';\nexport {getBrowser, isMobile} from './lib/get-browser';\nexport {isElectron} from './lib/is-electron';\n\n// ENVIRONMENT'S ASSERT IS 5-15KB, SO WE PROVIDE OUR OWN\nexport {assert} from './utils/assert';\n\n// TODO - wish we could just export a constant\n// export const isBrowser = checkIfBrowser();\n", "export default function assert(condition: unknown, message?: string): asserts condition {\n  if (!condition) {\n    throw new Error(message || 'Assertion failed');\n  }\n}\n", "// probe.gl\n// SPDX-License-Identifier: MIT\n// Copyright (c) vis.gl contributors\n\nimport assert from '../utils/assert';\n\n/**\n * Get logLevel from first argument:\n * - log(logLevel, message, args) => logLevel\n * - log(message, args) => 0\n * - log({logLevel, ...}, message, args) => logLevel\n * - log({logLevel, message, args}) => logLevel\n */\nexport function normalizeLogLevel(logLevel: unknown): number {\n  if (!logLevel) {\n    return 0;\n  }\n  let resolvedLevel;\n\n  switch (typeof logLevel) {\n    case 'number':\n      resolvedLevel = logLevel;\n      break;\n\n    case 'object':\n      // Backward compatibility\n      // TODO - deprecate `priority`\n      // @ts-expect-error\n      resolvedLevel = logLevel.logLevel || logLevel.priority || 0;\n      break;\n\n    default:\n      return 0;\n  }\n  // 'log level must be a number'\n  assert(Number.isFinite(resolvedLevel) && resolvedLevel >= 0);\n\n  return resolvedLevel;\n}\n\n/**\n * \"Normalizes\" the various argument patterns into an object with known types\n * - log(logLevel, message, args) => {logLevel, message, args}\n * - log(message, args) => {logLevel: 0, message, args}\n * - log({logLevel, ...}, message, args) => {logLevel, message, args}\n * - log({logLevel, message, args}) => {logLevel, message, args}\n */\nexport function normalizeArguments(opts: {\n  logLevel;\n  message;\n  collapsed?: boolean;\n  args?: IArguments | any[] | undefined;\n  opts?;\n}): NormalizedArguments {\n  const {logLevel, message} = opts;\n  opts.logLevel = normalizeLogLevel(logLevel);\n\n  // We use `arguments` instead of rest parameters (...args) because IE\n  // does not support the syntax. Rest parameters is transpiled to code with\n  // perf impact. Doing it here instead avoids constructing args when logging is\n  // disabled.\n  // TODO - remove when/if IE support is dropped\n  const args: any[] = opts.args ? Array.from(opts.args) : [];\n  // args should only contain arguments that appear after `message`\n  // eslint-disable-next-line no-empty\n  while (args.length && args.shift() !== message) {}\n\n  switch (typeof logLevel) {\n    case 'string':\n    case 'function':\n      if (message !== undefined) {\n        args.unshift(message);\n      }\n      opts.message = logLevel;\n      break;\n\n    case 'object':\n      Object.assign(opts, logLevel);\n      break;\n\n    default:\n  }\n\n  // Resolve functions into strings by calling them\n  if (typeof opts.message === 'function') {\n    opts.message = opts.message();\n  }\n  const messageType = typeof opts.message;\n  // 'log message must be a string' or object\n  assert(messageType === 'string' || messageType === 'object');\n\n  // original opts + normalized opts + opts arg + fixed up message\n  return Object.assign(opts, {args}, opts.opts);\n}\nexport type NormalizedArguments = {\n  logLevel: number;\n  message: any;\n  args: any[];\n  tag?: unknown;\n  method?: Function;\n  once?: boolean;\n  total?: number;\n  delta?: number;\n  [key: string]: any;\n};\n", "// probe.gl\n// SPDX-License-Identifier: MIT\n// Copyright (c) vis.gl contributors\n\nimport {Logger, LogFunction} from './logger';\nimport {NormalizedArguments, normalizeArguments, normalizeLogLevel} from './log-utils';\n\nconst noop = () => {};\n\nexport type NormalizedLogArguments = NormalizedArguments;\ntype LogType = 'log' | 'info' | 'once' | 'warn' | 'error' | 'table' | 'group' | 'groupEnd' | 'time';\n\ntype LogOptions = Partial<NormalizedLogArguments>;\n\n/**\n * Base logger that implements log level handling and once de-duplication.\n * Concrete loggers implement `_emit` to perform actual output.\n */\nexport abstract class BaseLog implements Logger {\n  userData: Record<string, unknown> = {};\n\n  protected _level: number;\n  protected _onceCache = new Set<unknown>();\n\n  constructor({level = 0}: {level?: number} = {}) {\n    this._level = level;\n  }\n\n  set level(newLevel: number) {\n    this.setLevel(newLevel);\n  }\n\n  get level(): number {\n    return this.getLevel();\n  }\n\n  setLevel(level: number): this {\n    this._level = level;\n    return this;\n  }\n\n  getLevel(): number {\n    return this._level;\n  }\n\n  // Unconditional logging\n\n  warn(message: string, ...args: unknown[]): LogFunction {\n    return this._log('warn', 0, message, args, {once: true});\n  }\n\n  error(message: string, ...args: unknown[]): LogFunction {\n    return this._log('error', 0, message, args);\n  }\n\n  // Conditional logging\n\n  log(logLevel, message?, ...args: unknown[]): LogFunction {\n    return this._log('log', logLevel, message, args);\n  }\n\n  info(logLevel, message?, ...args: unknown[]): LogFunction {\n    return this._log('info', logLevel, message, args);\n  }\n\n  once(logLevel, message?, ...args: unknown[]): LogFunction {\n    return this._log('once', logLevel, message, args, {once: true});\n  }\n\n  protected _log(\n    type: LogType,\n    logLevel: unknown,\n    message: unknown,\n    args: unknown[],\n    options: LogOptions = {}\n  ): LogFunction {\n    const normalized = normalizeArguments({\n      logLevel,\n      message,\n      args: this._buildArgs(logLevel, message, args),\n      opts: options\n    });\n\n    return this._createLogFunction(type, normalized, options);\n  }\n\n  protected _buildArgs(logLevel: unknown, message: unknown, args: unknown[]): unknown[] {\n    return [logLevel, message, ...args];\n  }\n\n  protected _createLogFunction(\n    type: LogType,\n    normalized: NormalizedLogArguments,\n    options: LogOptions\n  ): LogFunction {\n    if (!this._shouldLog(normalized.logLevel)) {\n      return noop;\n    }\n\n    const tag = this._getOnceTag(options.tag ?? normalized.tag ?? normalized.message);\n    if ((options.once || normalized.once) && tag !== undefined) {\n      if (this._onceCache.has(tag)) {\n        return noop;\n      }\n      this._onceCache.add(tag);\n    }\n\n    return this._emit(type, normalized);\n  }\n\n  protected _shouldLog(logLevel: unknown): boolean {\n    return this.getLevel() >= normalizeLogLevel(logLevel);\n  }\n\n  protected _getOnceTag(tag: unknown): unknown {\n    if (tag === undefined) {\n      return undefined;\n    }\n    try {\n      return typeof tag === 'string' ? tag : String(tag);\n    } catch {\n      return undefined;\n    }\n  }\n\n  /** Create the actual log function for this logger implementation. */\n  protected abstract _emit(type: LogType, normalized: NormalizedLogArguments): LogFunction;\n}\n\nexport {noop};\n", "// probe.gl, MIT license\n\nexport type StorageType = 'sessionStorage' | 'localStorage';\n\nfunction getStorage(type: StorageType): Storage | null {\n  try {\n    const storage: Storage = window[type];\n    const x = '__storage_test__';\n    storage.setItem(x, x);\n    storage.removeItem(x);\n    return storage;\n  } catch (e) {\n    return null;\n  }\n}\n\n// Store keys in local storage via simple interface\nexport class LocalStorage<Configuration extends {}> {\n  storage: Storage | null;\n  id: string;\n  config: Required<Configuration>;\n\n  constructor(\n    id: string,\n    defaultConfig: Required<Configuration>,\n    type: StorageType = 'sessionStorage'\n  ) {\n    this.storage = getStorage(type);\n    this.id = id;\n    this.config = defaultConfig;\n    this._loadConfiguration();\n  }\n\n  getConfiguration(): Required<Configuration> {\n    return this.config;\n  }\n\n  setConfiguration(configuration: Configuration): void {\n    Object.assign(this.config, configuration);\n    if (this.storage) {\n      const serialized = JSON.stringify(this.config);\n      this.storage.setItem(this.id, serialized);\n    }\n  }\n\n  // Get config from persistent store, if available\n  _loadConfiguration() {\n    let configuration = {};\n    if (this.storage) {\n      const serializedConfiguration = this.storage.getItem(this.id);\n      configuration = serializedConfiguration ? JSON.parse(serializedConfiguration) : {};\n    }\n    Object.assign(this.config, configuration);\n    return this;\n  }\n}\n", "// probe.gl, MIT license\n\nexport type FormatValueOptions = {\n  isInteger?: boolean;\n  maxElts?: number;\n  size?: number;\n};\n\n/**\n * Format time\n */\nexport function formatTime(ms: number): string {\n  let formatted;\n  if (ms < 10) {\n    formatted = `${ms.toFixed(2)}ms`;\n  } else if (ms < 100) {\n    formatted = `${ms.toFixed(1)}ms`;\n  } else if (ms < 1000) {\n    formatted = `${ms.toFixed(0)}ms`;\n  } else {\n    formatted = `${(ms / 1000).toFixed(2)}s`;\n  }\n  return formatted;\n}\n\nexport function leftPad(string: string, length: number = 8): string {\n  const padLength = Math.max(length - string.length, 0);\n  return `${' '.repeat(padLength)}${string}`;\n}\n\nexport function rightPad(string: string, length: number = 8): string {\n  const padLength = Math.max(length - string.length, 0);\n  return `${string}${' '.repeat(padLength)}`;\n}\n\nexport function formatValue(v: unknown, options: FormatValueOptions = {}): string {\n  const EPSILON = 1e-16;\n  const {isInteger = false} = options;\n  if (Array.isArray(v) || ArrayBuffer.isView(v)) {\n    return formatArrayValue(v, options);\n  }\n  if (!Number.isFinite(v)) {\n    return String(v);\n  }\n  // @ts-expect-error\n  if (Math.abs(v) < EPSILON) {\n    return isInteger ? '0' : '0.';\n  }\n  if (isInteger) {\n    // @ts-expect-error\n    return v.toFixed(0);\n  }\n  // @ts-expect-error\n  if (Math.abs(v) > 100 && Math.abs(v) < 10000) {\n    // @ts-expect-error\n    return v.toFixed(0);\n  }\n  // @ts-expect-error\n  const string = v.toPrecision(2);\n  const decimal = string.indexOf('.0');\n  return decimal === string.length - 2 ? string.slice(0, -1) : string;\n}\n\n/** Helper to formatValue */\nfunction formatArrayValue(v: any, options: FormatValueOptions) {\n  const {maxElts = 16, size = 1} = options;\n  let string = '[';\n  for (let i = 0; i < v.length && i < maxElts; ++i) {\n    if (i > 0) {\n      string += `,${i % size === 0 ? ' ' : ''}`;\n    }\n    string += formatValue(v[i], options);\n  }\n  const terminator = v.length > maxElts ? '...' : ']';\n  return `${string}${terminator}`;\n}\n", "import {isBrowser} from '@probe.gl/env';\n\nexport enum COLOR {\n  BLACK = 30,\n  RED = 31,\n  GREEN = 32,\n  YELLOW = 33,\n  BLUE = 34,\n  MAGENTA = 35,\n  CYAN = 36,\n  WHITE = 37,\n\n  BRIGHT_BLACK = 90,\n  BRIGHT_RED = 91,\n  BRIGHT_GREEN = 92,\n  BRIGHT_YELLOW = 93,\n  BRIGHT_BLUE = 94,\n  BRIGHT_MAGENTA = 95,\n  BRIGHT_CYAN = 96,\n  BRIGHT_WHITE = 97\n}\n\nconst BACKGROUND_INCREMENT = 10;\n\nfunction getColor(color: string | COLOR): number {\n  if (typeof color !== 'string') {\n    return color;\n  }\n  color = color.toUpperCase();\n  return COLOR[color] || COLOR.WHITE;\n}\n\nexport function addColor(\n  string: string,\n  color: string | COLOR,\n  background?: string | COLOR\n): string {\n  if (!isBrowser && typeof string === 'string') {\n    if (color) {\n      const colorCode = getColor(color);\n      s