x connects to the previous and the first vertex in the fan. */\n  TRIANGLE_FAN = 0x0006,\n\n  // Blending modes\n  // Constants passed to blendFunc() or blendFuncSeparate() to specify the blending mode (for both, RBG and alpha, or separately).\n  /** Passed to blendFunc or blendFuncSeparate to turn off a component. */\n  ZERO = 0,\n  /** Passed to blendFunc or blendFuncSeparate to turn on a component. */\n  ONE = 1,\n  /** Passed to blendFunc or blendFuncSeparate to multiply a component by the source elements color. */\n  SRC_COLOR = 0x0300,\n  /** Passed to blendFunc or blendFuncSeparate to multiply a component by one minus the source elements color. */\n  ONE_MINUS_SRC_COLOR = 0x0301,\n  /** Passed to blendFunc or blendFuncSeparate to multiply a component by the source's alpha. */\n  SRC_ALPHA = 0x0302,\n  /** Passed to blendFunc or blendFuncSeparate to multiply a component by one minus the source's alpha. */\n  ONE_MINUS_SRC_ALPHA = 0x0303,\n  /** Passed to blendFunc or blendFuncSeparate to multiply a component by the destination's alpha. */\n  DST_ALPHA = 0x0304,\n  /** Passed to blendFunc or blendFuncSeparate to multiply a component by one minus the destination's alpha. */\n  ONE_MINUS_DST_ALPHA = 0x0305,\n  /** Passed to blendFunc or blendFuncSeparate to multiply a component by the destination's color. */\n  DST_COLOR = 0x0306,\n  /** Passed to blendFunc or blendFuncSeparate to multiply a component by one minus the destination's color. */\n  ONE_MINUS_DST_COLOR = 0x0307,\n  /** Passed to blendFunc or blendFuncSeparate to multiply a component by the minimum of source's alpha or one minus the destination's alpha. */\n  SRC_ALPHA_SATURATE = 0x0308,\n  /** Passed to blendFunc or blendFuncSeparate to specify a constant color blend function. */\n  CONSTANT_COLOR = 0x8001,\n  /** Passed to blendFunc or blendFuncSeparate to specify one minus a constant color blend function. */\n  ONE_MINUS_CONSTANT_COLOR = 0x8002,\n  /** Passed to blendFunc or blendFuncSeparate to specify a constant alpha blend function. */\n  CONSTANT_ALPHA = 0x8003,\n  /** Passed to blendFunc or blendFuncSeparate to specify one minus a constant alpha blend function. */\n  ONE_MINUS_CONSTANT_ALPHA = 0x8004,\n\n  // Blending equations\n  // Constants passed to blendEquation() or blendEquationSeparate() to control\n  // how the blending is calculated (for both, RBG and alpha, or separately).\n\n  /** Passed to blendEquation or blendEquationSeparate to set an addition blend function. */\n  /** Passed to blendEquation or blendEquationSeparate to specify a subtraction blend function (source - destination). */\n  /** Passed to blendEquation or blendEquationSeparate to specify a reverse subtraction blend function (destination - source). */\n  FUNC_ADD = 0x8006,\n  FUNC_SUBTRACT = 0x800a,\n  FUNC_REVERSE_SUBTRACT = 0x800b,\n\n  // Getting GL parameter information\n  // Constants passed to getParameter() to specify what information to return.\n\n  /** Passed to getParameter to get the current RGB blend function. */\n  BLEND_EQUATION = 0x8009,\n  /** Passed to getParameter to get the current RGB blend function. Same as BLEND_EQUATION */\n  BLEND_EQUATION_RGB = 0x8009,\n  /** Passed to getParameter to get the current alpha blend function. Same as BLEND_EQUATION */\n  BLEND_EQUATION_ALPHA = 0x883d,\n  /** Passed to getParameter to get the current destination RGB blend function. */\n  BLEND_DST_RGB = 0x80c8,\n  /** Passed to getParameter to get the current destination RGB blend function. */\n  BLEND_SRC_RGB = 0x80c9,\n  /** Passed to getParameter to get the current destination alpha blend function. */\n  BLEND_DST_ALPHA = 0x80ca,\n  /** Passed to getParameter to get the current source alpha blend function. */\n  BLEND_SRC_ALPHA = 0x80cb,\n\n  /** Passed to getParameter to return a the current blend color. */\n  BLEND_COLOR = 0x8005,\n  /** Passed to getParameter to get the array buffer binding. */\n  ARRAY_BUFFER_BINDING = 0x8894,\n  /** Passed to getParameter to get the current element array buffer. */\n  ELEMENT_ARRAY_BUFFER_BINDING = 0x8895,\n  /** Passed to getParameter to get the current lineWidth (set by the lineWidth method). */\n  LINE_WIDTH = 0x0b21,\n  /** Passed to getParameter to get the current size of a point drawn with gl.POINTS */\n  ALIASED_POINT_SIZE_RANGE = 0x846d,\n  /** Passed to getParameter to get the range of available widths for a line. Returns a length-2 array with the lo value at 0, and hight at 1. */\n  ALIASED_LINE_WIDTH_RANGE = 0x846e,\n  /** Passed to getParameter to get the current value of cullFace. Should return FRONT, BACK, or FRONT_AND_BACK */\n  CULL_FACE_MODE = 0x0b45,\n  /** Passed to getParameter to determine the current value of frontFace. Should return CW or CCW. */\n  FRONT_FACE = 0x0b46,\n  /** Passed to getParameter to return a length-2 array of floats giving the current depth range. */\n  DEPTH_RANGE = 0x0b70,\n  /** Passed to getParameter to determine if the depth write mask is enabled. */\n\n  DEPTH_WRITEMASK = 0x0b72,\n  /** Passed to getParameter to determine the current depth clear value. */\n  DEPTH_CLEAR_VALUE = 0x0b73,\n  /** Passed to getParameter to get the current depth function. Returns NEVER, ALWAYS, LESS, EQUAL, LEQUAL, GREATER, GEQUAL, or NOTEQUAL. */\n  DEPTH_FUNC = 0x0b74,\n  /** Passed to getParameter to get the value the stencil will be cleared to. */\n  STENCIL_CLEAR_VALUE = 0x0b91,\n  /** Passed to getParameter to get the current stencil function. Returns NEVER, ALWAYS, LESS, EQUAL, LEQUAL, GREATER, GEQUAL, or NOTEQUAL. */\n  STENCIL_FUNC = 0x0b92,\n  /** Passed to getParameter to get the current stencil fail function. Should return KEEP, REPLACE, INCR, DECR, INVERT, INCR_WRAP, or DECR_WRAP. */\n  STENCIL_FAIL = 0x0b94,\n  /** Passed to getParameter to get the current stencil fail function should the depth buffer test fail. Should return KEEP, REPLACE, INCR, DECR, INVERT, INCR_WRAP, or DECR_WRAP. */\n  STENCIL_PASS_DEPTH_FAIL = 0x0b95,\n  /** Passed to getParameter to get the current stencil fail function should the depth buffer test pass. Should return KEEP, REPLACE, INCR, DECR, INVERT, INCR_WRAP, or DECR_WRAP. */\n  STENCIL_PASS_DEPTH_PASS = 0x0b96,\n  /** Passed to getParameter to get the reference value used for stencil tests. */\n  STENCIL_REF = 0x0b97,\n  STENCIL_VALUE_MASK = 0x0b93,\n  STENCIL_WRITEMASK = 0x0b98,\n  STENCIL_BACK_FUNC = 0x8800,\n  STENCIL_BACK_FAIL = 0x8801,\n  STENCIL_BACK_PASS_DEPTH_FAIL = 0x8802,\n  STENCIL_BACK_PASS_DEPTH_PASS = 0x8803,\n  STENCIL_BACK_REF = 0x8ca3,\n  STENCIL_BACK_VALUE_MASK = 0x8ca4,\n  STENCIL_BACK_WRITEMASK = 0x8ca5,\n\n  /** An Int32Array with four elements for the current viewport dimensions. */\n  VIEWPORT = 0x0ba2,\n  /** An Int32Array with four elements for the current scissor box dimensions. */\n  SCISSOR_BOX = 0x0c10,\n  COLOR_CLEAR_VALUE = 0x0c22,\n  COLOR_WRITEMASK = 0x0c23,\n  UNPACK_ALIGNMENT = 0x0cf5,\n  PACK_ALIGNMENT = 0x0d05,\n  MAX_TEXTURE_SIZE = 0x0d33,\n  MAX_VIEWPORT_DIMS = 0x0d3a,\n  SUBPIXEL_BITS = 0x0d50,\n  RED_BITS = 0x0d52,\n  GREEN_BITS = 0x0d53,\n  BLUE_BITS = 0x0d54,\n  ALPHA_BITS = 0x0d55,\n  DEPTH_BITS = 0x0d56,\n  STENCIL_BITS = 0x0d57,\n  POLYGON_OFFSET_UNITS = 0x2a00,\n  POLYGON_OFFSET_FACTOR = 0x8038,\n  TEXTURE_BINDING_2D = 0x8069,\n  SAMPLE_BUFFERS = 0x80a8,\n  SAMPLES = 0x80a9,\n  SAMPLE_COVERAGE_VALUE = 0x80aa,\n  SAMPLE_COVERAGE_INVERT = 0x80ab,\n  COMPRESSED_TEXTURE_FORMATS = 0x86a3,\n  VENDOR = 0x1f00,\n  RENDERER = 0x1f01,\n  VERSION = 0x1f02,\n  IMPLEMENTATION_COLOR_READ_TYPE = 0x8b9a,\n  IMPLEMENTATION_COLOR_READ_FORMAT = 0x8b9b,\n  BROWSER_DEFAULT_WEBGL = 0x9244,\n\n  // Buffers\n  // Constants passed to bufferData(), bufferSubData(), bindBuffer(), or\n  // getBufferParameter().\n\n  /** Passed to bufferData as a hint about whether the contents of the buffer are likely to be used often and not change often. */\n  STATIC_DRAW = 0x88e4,\n  /** Passed to bufferData as a hint about whether the contents of the buffer are likely to not be used often. */\n  STREAM_DRAW = 0x88e0,\n  /** Passed to bufferData as a hint about whether the contents of the buffer are likely to be used often and change often. */\n  DYNAMIC_DRAW = 0x88e8,\n  /** Passed to bindBuffer or bufferData to specify the type of buffer being used. */\n  ARRAY_BUFFER = 0x8892,\n  /** Passed to bindBuffer or bufferData to specify the type of buffer being used. */\n  ELEMENT_ARRAY_BUFFER = 0x8893,\n  /** Passed to getBufferParameter to get a buffer's size. */\n  BUFFER_SIZE = 0x8764,\n  /** Passed to getBufferParameter to get the hint for the buffer passed in when it was created. */\n  BUFFER_USAGE = 0x8765,\n\n  // Vertex attributes\n  // Constants passed to getVertexAttrib().\n\n  /** Passed to getVertexAttrib to read back the current vertex attribute. */\n  CURRENT_VERTEX_ATTRIB = 0x8626,\n  VERTEX_ATTRIB_ARRAY_ENABLED = 0x8622,\n  VERTEX_ATTRIB_ARRAY_SIZE = 0x8623,\n  VERTEX_ATTRIB_ARRAY_STRIDE = 0x8624,\n  VERTEX_ATTRIB_ARRAY_TYPE = 0x8625,\n  VERTEX_ATTRIB_ARRAY_NORMALIZED = 0x886a,\n  VERTEX_ATTRIB_ARRAY_POINTER = 0x8645,\n  VERTEX_ATTRIB_ARRAY_BUFFER_BINDING = 0x889f,\n\n  // Culling\n  // Constants passed to cullFace().\n\n  /** Passed to enable/disable to turn on/off culling. Can also be used with getParameter to find the current culling method. */\n  CULL_FACE = 0x0b44,\n  /** Passed to cullFace to specify that only front faces should be culled. */\n  FRONT = 0x0404,\n  /** Passed to cullFace to specify that only back faces should be culled. */\n  BACK = 0x0405,\n  /** Passed to cullFace to specify that front and back faces should be culled. */\n  FRONT_AND_BACK = 0x0408,\n\n  // Enabling and disabling\n  // Constants passed to enable() or disable().\n\n  /** Passed to enable/disable to turn on/off blending. Can also be used with getParameter to find the current blending method. */\n  BLEND = 0x0be2,\n  /** Passed to enable/disable to turn on/off the depth test. Can also be used with getParameter to query the depth test. */\n  DEPTH_TEST = 0x0b71,\n  /** Passed to enable/disable to turn on/off dithering. Can also be used with getParameter to find the current dithering method. */\n  DITHER = 0x0bd0,\n  /** Passed to enable/disable to turn on/off the polygon offset. Useful for rendering hidden-line images, decals, and or solids with highlighted edges. Can also be used with getParameter to query the scissor test. */\n  POLYGON_OFFSET_FILL = 0x8037,\n  /** Passed to enable/disable to turn on/off the alpha to coverage. Used in multi-sampling alpha channels. */\n  SAMPLE_ALPHA_TO_COVERAGE = 0x809e,\n  /** Passed to enable/disable to turn on/off the sample coverage. Used in multi-sampling. */\n  SAMPLE_COVERAGE = 0x80a0,\n  /** Passed to enable/disable to turn on/off the scissor test. Can also be used with getParameter to query the scissor test. */\n  SCISSOR_TEST = 0x0c11,\n  /** Passed to enable/disable to turn on/off the stencil test. Can also be used with getParameter to query the stencil test. */\n  STENCIL_TEST = 0x0b90,\n\n  // Errors\n  // Constants returned from getError().\n\n  /** Returned from getError(). */\n  NO_ERROR = 0,\n  /** Returned from getError(). */\n  INVALID_ENUM = 0x0500,\n  /** Returned from getError(). */\n  INVALID_VALUE = 0x0501,\n  /** Returned from getError(). */\n  INVALID_OPERATION = 0x0502,\n  /** Returned from getError(). */\n  OUT_OF_MEMORY = 0x0505,\n  /** Returned from getError(). */\n  CONTEXT_LOST_WEBGL = 0x9242,\n\n  // Front face directions\n  // Constants passed to frontFace().\n\n  /** Passed to frontFace to specify the front face of a polygon is drawn in the clockwise direction */\n  CW = 0x0900,\n  /** Passed to frontFace to specify the front face of a polygon is drawn in the counter clockwise direction */\n  CCW = 0x0901,\n\n  // Hints\n  // Constants passed to hint()\n\n  /** There is no preference for this behavior. */\n  DONT_CARE = 0x1100,\n  /** The most efficient behavior should be used. */\n  FASTEST = 0x1101,\n  /** The most correct or the highest quality option should be used. */\n  NICEST = 0x1102,\n  /** Hint for the quality of filtering when generating mipmap images with WebGLRenderingContext.generateMipmap(). */\n  GENERATE_MIPMAP_HINT = 0x8192,\n\n  // Data types\n\n  BYTE = 0x1400,\n  UNSIGNED_BYTE = 0x1401,\n  SHORT = 0x1402,\n  UNSIGNED_SHORT = 0x1403,\n  INT = 0x1404,\n  UNSIGNED_INT = 0x1405,\n  FLOAT = 0x1406,\n  DOUBLE = 0x140a,\n\n  // Pixel formats\n\n  DEPTH_COMPONENT = 0x1902,\n  ALPHA = 0x1906,\n  RGB = 0x1907,\n  RGBA = 0x1908,\n  LUMINANCE = 0x1909,\n  LUMINANCE_ALPHA = 0x190a,\n\n  // Pixel types\n\n  // UNSIGNED_BYTE = 0x1401,\n  UNSIGNED_SHORT_4_4_4_4 = 0x8033,\n  UNSIGNED_SHORT_5_5_5_1 = 0x8034,\n  UNSIGNED_SHORT_5_6_5 = 0x8363,\n\n  // Shaders\n  // Constants passed to createShader() or getShaderParameter()\n\n  /** Passed to createShader to define a fragment shader. */\n  FRAGMENT_SHADER = 0x8b30,\n  /** Passed to createShader to define a vertex shader */\n  VERTEX_SHADER = 0x8b31,\n  /** Passed to getShaderParameter to get the status of the compilation. Returns false if the shader was not compiled. You can then query getShaderInfoLog to find the exact error */\n  COMPILE_STATUS = 0x8b81,\n  /** Passed to getShaderParameter to determine if a shader was deleted via deleteShader. Returns true if it was, false otherwise. */\n  DELETE_STATUS = 0x8b80,\n  /** Passed to getProgramParameter after calling linkProgram to determine if a program was linked correctly. Returns false if there were errors. Use getProgramInfoLog to find the exact error. */\n  LINK_STATUS = 0x8b82,\n  /** Passed to getProgramParameter after calling validateProgram to determine if it is valid. Returns false if errors were found. */\n  VALIDATE_STATUS = 0x8b83,\n  /** Passed to getProgramParameter after calling attachShader to determine if the shader was attached correctly. Returns false if errors occurred. */\n  ATTACHED_SHADERS = 0x8b85,\n  /** Passed to getProgramParameter to get the number of attributes active in